30	  HeaderNavDefinition,
31	  HeaderNavItemDefinition,
32	  HeaderNavGroupDefinition,
33	} from './HeaderNavDefinition';
34	import { HeaderNavIndicators } from './HeaderNavIndicators';
35	import { MenuTrigger, Menu, MenuItem } from '../Menu';
36	import type {
37	  HeaderNavLinkProps,
38	  HeaderNavTabGroup,
39	  HeaderNavTabItem,
40	} from './types';
41	
42	function isTabGroup(tab: HeaderNavTabItem): tab is HeaderNavTabGroup {
43	  return 'items' in tab;
44	}
45	
46	function HeaderNavLink(props: HeaderNavLinkProps) {
47	  const { ownProps, analytics } = useDefinition(HeaderNavItemDefinition, props);
48	  const { id, label, href, active, registerRef, onHighlight } = ownProps;
49	
50	  const linkRef = useRef<HTMLAnchorElement>(null);
51	  const { linkProps } = useLink({ href }, linkRef);
52	  const { hoverProps } = useHover({
53	    onHoverStart: () => onHighlight(id),
54	    onHoverEnd: () => onHighlight(null),
55	  });
56	
57	  const handleClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
58	    linkProps.onClick?.(e);
59	    analytics.captureEvent('click', label, {
60	      attributes: { to: href },
61	    });
62	  };
63	
64	  return (
65	    <li>
66	      <a
67	        {...linkProps}
68	        {...hoverProps}
69	        ref={el => {
70	          (
71	            linkRef as React.MutableRefObject<HTMLAnchorElement | null>
72	          ).current = el;
73	          registerRef(id, el);
74	        }}
75	        href={href}
76	        className={ownProps.classes.root}
77	        aria-current={active ? 'page' : undefined}
78	        onClick={handleClick}
79	        onFocus={() => onHighlight(id)}
80	        onBlur={() => onHighlight(null)}
81	      >
82	        {label}
83	      </a>
84	    </li>
85	  );
86	}
87	
88	interface HeaderNavGroupItemProps {
89	  group: HeaderNavTabGroup;
90	  active: boolean;
91	  activeChildId?: string;
92	  registerRef: (key: string, el: HTMLElement | null) => void;
93	  onHighlight: (key: string | null) => void;
94	}
95	
96	function HeaderNavGroupItem(props: HeaderNavGroupItemProps) {
97	  const { group, active, activeChildId, registerRef, onHighlight } = props;
98	  const { ownProps } = useDefinition(HeaderNavGroupDefinition, {});
99	  const { hoverProps } = useHover({
100	    onHoverStart: () => onHighlight(group.id),
101	    onHoverEnd: () => onHighlight(null),
102	  });
103	
104	  return (
105	    <li>
106	      <MenuTrigger>
107	        <RAButton
108	          ref={el => {
109	            registerRef(group.id, el);
110	          }}
111	          className={ownProps.classes.root}
112	          aria-current={active ? 'page' : undefined}
113	          {...hoverProps}
114	          onFocus={() => onHighlight(group.id)}
115	          onBlur={() => onHighlight(null)}
116	        >
117	          {group.label}
118	          <RiArrowDownSLine size={16} />
119	        </RAButton>
120	        <Menu
121	          selectionMode="single"
122	          selectedKeys={new Set(activeChildId ? [activeChildId] : [])}
123	        >
124	          {group.items.map(item => (
125	            <MenuItem key={item.id} id={item.id} href={item.href}>
126	              {item.label}
127	            </MenuItem>
128	          ))}
129	        </Menu>
130	      </MenuTrigger>
131	    </li>
132	  );
133	}
134	
135	interface HeaderNavProps {
136	  tabs: HeaderNavTabItem[];
137	  activeTabId?: string | null;
138	}
139	
140	function useAutoActiveTabId(tabs: HeaderNavTabItem[]): string | undefined {
141	  const basePath = useResolvedPath('.').pathname;
142	  const { pathname } = useLocation();
143	
144	  return useMemo(() => {
145	    const allTabs = tabs.flatMap(tab => (isTabGroup(tab) ? tab.items : [tab]));
146	    const routeObjects = allTabs.map(tab => ({
147	      path: `${resolvePath(tab.href, basePath).pathname}/*`,
148	      id: tab.id,
149	    }));
150	    const matches = matchRoutes(routeObjects, pathname);
151	    return matches?.[0]?.route.id;
152	  }, [tabs, basePath, pathname]);
153	}
154	
155	function HeaderNavAutoDetect(props: { tabs: HeaderNavTabItem[] }) {
156	  const activeTabId = useAutoActiveTabId(props.tabs);
157	  return <HeaderNavInner tabs={props.tabs} activeTabId={activeTabId} />;
158	}
159	
