181	          return { activeKey: item.id, activeChildId: child.id };
182	        }
183	      } else if (item.id === activeTabId) {
184	        return { activeKey: item.id, activeChildId: undefined };
185	      }
186	    }
187	    return { activeKey: undefined, activeChildId: undefined };
188	  }, [activeTabId, tabs]);
189	
190	  const registerRef = useCallback((key: string, el: HTMLElement | null) => {
191	    if (el) {
192	      itemRefs.current.set(key, el);
193	    } else {
194	      itemRefs.current.delete(key);
195	    }
196	  }, []);
197	
198	  return (
199	    <nav
200	      ref={navRef}
201	      aria-label="Content navigation"
202	      className={classes.root}
203	      data-focus-visible={isFocusVisible || undefined}
204	    >
