          ).current = el;
          registerRef(id, el);
        }}
        href={href}
        className={ownProps.classes.root}
        aria-current={active ? 'page' : undefined}
        onClick={handleClick}
        onFocus={() => onHighlight(id)}
        onBlur={() => onHighlight(null)}
      >
        {label}
      </a>
    </li>
  );
}

