interface HeaderNavProps {
  tabs: HeaderNavTabItem[];
  activeTabId?: string | null;
}

function useAutoActiveTabId(tabs: HeaderNavTabItem[]): string | undefined {
  const basePath = useResolvedPath('.').pathname;
  const { pathname } = useLocation();

  return useMemo(() => {
