            <HeaderNavLink
              key={item.id}
              id={item.id}
              label={item.label}
              href={item.href}
              active={activeKey === item.id}
              registerRef={registerRef}
              onHighlight={setHighlightedKey}
            />
          ),
        )}
      </ul>
      <HeaderNavIndicators
        navRef={navRef}
        itemRefs={itemRefs}
        activeKey={activeKey}
        highlightedKey={highlightedKey}
        classes={{ active: classes.active, hovered: classes.hovered }}
      />
    </nav>
  );
}

